<?php $mode = $mode ?? 'create'; $product = $product ?? []; $title = $mode === 'edit' ? 'Edit Item' : 'Add Inventory Item'; $itemTypes = $itemTypes ?? \Product::itemTypes(); ?>
<div class="row justify-content-center"><div class="col-lg-8"><div class="card shadow-sm border-0"><div class="card-body">
<h2 class="h4 mb-4"><?= htmlspecialchars($title) ?></h2>
<?php if (!empty($error)): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<form method="post" class="row g-3"><?= $this->csrfField() ?>
<div class="col-md-6"><label class="form-label">Category</label><select class="form-select" name="item_category" id="item-category" required><?php foreach ($itemTypes as $category => $types): ?><option value="<?= htmlspecialchars($category) ?>" <?= ($product['item_category'] ?? '') === $category ? 'selected' : '' ?>><?= htmlspecialchars($category === 'Sim cards' ? 'SIM cards / Lines' : $category) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label">Type</label><select class="form-select" name="item_type" id="item-type" required></select></div>
<div class="col-md-6"><label class="form-label">Serial number / IMEI (digits only)</label><input class="form-control" name="identifier" inputmode="numeric" pattern="[0-9]*" value="<?= htmlspecialchars($product['identifier'] ?? $product['imei'] ?? '') ?>"><div class="form-text">Optional; any number of digits is accepted.</div></div>
<div class="col-md-6"><label class="form-label">Quantity</label><input class="form-control" type="number" min="1" name="quantity" value="<?= (int) ($product['quantity'] ?? 1) ?>" required></div>
<div class="col-md-6"><label class="form-label">Cost Price</label><input class="form-control" type="number" step="0.01" min="0" name="cost_price" value="<?= htmlspecialchars((string) ($product['cost_price'] ?? 0)) ?>"></div>
<div class="col-md-6"><label class="form-label">Selling Price</label><input class="form-control" type="number" step="0.01" min="0" name="selling_price" value="<?= htmlspecialchars((string) ($product['selling_price'] ?? 0)) ?>"></div>
<div class="col-12"><button class="btn btn-primary" type="submit">Save Item</button> <a class="btn btn-outline-secondary" href="/index.php?controller=inventory">Back to list</a></div></form>
</div></div></div></div>
<script>const itemTypes=<?= json_encode($itemTypes, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;const category=document.getElementById('item-category'),type=document.getElementById('item-type'),selected=<?= json_encode($product['item_type'] ?? '') ?>;function refreshTypes(){type.innerHTML='';(itemTypes[category.value]||[]).forEach(value=>{const o=document.createElement('option');o.value=value;o.textContent=value;o.selected=value===selected;type.append(o);});}category.addEventListener('change',refreshTypes);refreshTypes();</script>
